const assets = {"/":{"body":"","contentType":"text/html; charset=utf-8"},"/styles.css":{"body":"","contentType":"text/css; charset=utf-8"},"/script.js":{"body":"","contentType":"text/javascript; charset=utf-8"},"/og.png":{"body":"","contentType":"image/png"}};

function decodeBase64(value) {
  const binary = atob(value);
  return Uint8Array.from(binary, (character) => character.charCodeAt(0));
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const asset = assets[url.pathname];

    if (!asset) {
      return new Response("Página no encontrada", {
        status: 404,
        headers: { "content-type": "text/plain; charset=utf-8" },
      });
    }

    return new Response(decodeBase64(asset.body), {
      headers: {
        "content-type": asset.contentType,
        "cache-control": url.pathname === "/" ? "no-cache" : "public, max-age=86400",
        "x-content-type-options": "nosniff",
      },
    });
  },
};
